{"content": "// 4-requester round-robin arbiter, synthesizable Verilog-2001.
// Combinational grant: lowest-index requester at or after rr_ptr (wraps).
// Sequential pointer update: priority moves past the granted requester.
// The combinational block uses an explicit sensitivity list and single-line
// `default:` branches on purpose: pipelines/rtl/mutate.py pattern-matches them.
module round_robin_arbiter (
    input  wire       clk,
    input  wire       rst_n,
    input  wire [3:0] req,
    output reg  [3:0] grant
);
    reg [1:0] rr_ptr;

    always @(req or rr_ptr) begin
        case (rr_ptr)
            2'd0: begin
                if (req[0])      grant = 4'b0001;
                else if (req[1]) grant = 4'b0010;
                else if (req[2]) grant = 4'b0100;
                else if (req[3]) grant = 4'b1000;
                else             grant = 4'b0000;
            end
            2'd1: begin
                if (req[1])      grant = 4'b0010;
                else if (req[2]) grant = 4'b0100;
                else if (req[3]) grant = 4'b1000;
                else if (req[0]) grant = 4'b0001;
                else             grant = 4'b0000;
            end
            2'd2: begin
                if (req[2])      grant = 4'b0100;
                else if (req[3]) grant = 4'b1000;
                else if (req[0]) grant = 4'b0001;
                else if (req[1]) grant = 4'b0010;
                else             grant = 4'b0000;
            end
            2'd3: begin
                if (req[3])      grant = 4'b1000;
                else if (req[0]) grant = 4'b0001;
                else if (req[1]) grant = 4'b0010;
                else if (req[2]) grant = 4'b0100;
                else             grant = 4'b0000;
            end
            default: grant = 4'b0000;
        endcase
    end

    always @(posedge clk) begin
        if (!rst_n) begin
            rr_ptr <= 2'd0;
        end else begin
            case (grant)
                4'b0001: rr_ptr <= 2'd1;
                4'b0010: rr_ptr <= 2'd2;
                4'b0100: rr_ptr <= 2'd3;
                4'b1000: rr_ptr <= 2'd0;
                default: rr_ptr <= 2'd0;
            endcase
        end
    end
endmodule
