{"content": "// AXI-Stream skid buffer (2-deep elastic buffer), synthesizable Verilog-2001.
// Breaks the tready timing path: when the downstream stalls, one beat is held
// in the skid register so s_axis_tready can deassert a cycle later without
// losing data.
module axis_skid_buffer #(
    parameter WIDTH = 32
)(
    input  wire             clk,
    input  wire             rst_n,
    input  wire [WIDTH-1:0] s_axis_tdata,
    input  wire             s_axis_tvalid,
    output wire             s_axis_tready,
    output wire [WIDTH-1:0] m_axis_tdata,
    output wire             m_axis_tvalid,
    input  wire             m_axis_tready
);
    reg [WIDTH-1:0] skid_data;
    reg             skid_valid;
    reg [WIDTH-1:0] out_data;
    reg             out_valid;

    assign s_axis_tready = !skid_valid;
    assign m_axis_tdata  = out_data;
    assign m_axis_tvalid = out_valid;

    always @(posedge clk) begin
        if (!rst_n) begin
            skid_data  <= {WIDTH{1'b0}};
            skid_valid <= 1'b0;
        end else begin
            if (s_axis_tvalid && s_axis_tready && out_valid && !m_axis_tready) begin
                skid_data  <= s_axis_tdata;
                skid_valid <= 1'b1;
            end else if (m_axis_tready && out_valid && skid_valid) begin
                skid_valid <= 1'b0;
            end
        end
    end

    always @(posedge clk) begin
        if (!rst_n) begin
            out_data  <= {WIDTH{1'b0}};
            out_valid <= 1'b0;
        end else begin
            if (m_axis_tready || !out_valid) begin
                if (skid_valid) begin
                    out_data  <= skid_data;
                    out_valid <= 1'b1;
                end else if (s_axis_tvalid) begin
                    out_data  <= s_axis_tdata;
                    out_valid <= 1'b1;
                end else begin
                    out_valid <= 1'b0;
                end
            end
        end
    end
endmodule
