{"content": "// Self-checking testbench for sync_fifo. Prints "TEST PASSED" on success,
// "TEST FAILED" + $fatal on mismatch. Verilog-2001, iverilog-compatible.
`timescale 1ns/1ps
module tb_sync_fifo;
    localparam WIDTH = 8;
    localparam DEPTH = 16;

    reg                 clk = 1'b0;
    reg                 rst_n = 1'b0;
    reg                 wr_en = 1'b0;
    reg  [WIDTH-1:0]    wr_data = {WIDTH{1'b0}};
    wire                full;
    reg                 rd_en = 1'b0;
    wire [WIDTH-1:0]    rd_data;
    wire                empty;

    integer errors = 0;
    integer i;

    sync_fifo #(.WIDTH(WIDTH), .DEPTH(DEPTH)) dut (
        .clk(clk), .rst_n(rst_n),
        .wr_en(wr_en), .wr_data(wr_data), .full(full),
        .rd_en(rd_en), .rd_data(rd_data), .empty(empty)
    );

    always #5 clk = ~clk;

    task check;
        input cond;
        input [127:0] msg;
        begin
            if (!cond) begin
                errors = errors + 1;
                $display("FAIL: %0s at time %0t", msg, $time);
            end
        end
    endtask

    initial begin
        // reset
        repeat (3) @(posedge clk);
        rst_n = 1'b1;
        @(posedge clk);
        check(empty, "fifo not empty after reset");
        check(!full, "fifo full after reset");

        // fill completely
        for (i = 0; i < DEPTH; i = i + 1) begin
            wr_en = 1'b1;
            wr_data = i + 8'h10;
            @(posedge clk);
        end
        wr_en = 1'b0;
        check(full, "fifo not full after DEPTH writes");

        // drain completely, verify order
        for (i = 0; i < DEPTH; i = i + 1) begin
            rd_en = 1'b1;
            #1;
            check(rd_data == i + 8'h10, "read data order mismatch");
            @(posedge clk);
        end
        rd_en = 1'b0;
        #1;
        check(empty, "fifo not empty after drain");

        // interleaved write/read
        rst_n = 1'b0;
        repeat (2) @(posedge clk);
        rst_n = 1'b1;
        @(posedge clk);
        for (i = 0; i < 40; i = i + 1) begin
            wr_en = 1'b1; wr_data = i;
            rd_en = (i > 4);
            @(posedge clk);
        end
        wr_en = 1'b0; rd_en = 1'b0;

        if (errors == 0) begin
            $display("TEST PASSED");
        end else begin
            $display("TEST FAILED (%0d errors)", errors);
            $fatal(1);
        end
        $finish;
    end

    initial begin
        #100000;
        $display("TEST FAILED (timeout)");
        $fatal(1);
    end
endmodule
