{"content": "// Self-checking testbench for round_robin_arbiter. Verilog-2001, iverilog-compatible.
`timescale 1ns/1ps
module tb_round_robin_arbiter;
    reg        clk = 1'b0;
    reg        rst_n = 1'b0;
    reg  [3:0] req = 4'b0000;
    wire [3:0] grant;

    integer errors = 0;
    integer i;
    integer g0, g1, g2, g3;

    round_robin_arbiter dut (
        .clk(clk), .rst_n(rst_n), .req(req), .grant(grant)
    );

    always #5 clk = ~clk;

    function is_onehot_or_zero;
        input [3:0] g;
        begin
            is_onehot_or_zero = (g == 4'b0000) || (g == 4'b0001) ||
                                (g == 4'b0010) || (g == 4'b0100) || (g == 4'b1000);
        end
    endfunction

    initial begin
        repeat (3) @(posedge clk);
        rst_n = 1'b1;
        @(posedge clk);

        // no request -> no grant
        req = 4'b0000;
        #1;
        if (grant !== 4'b0000) begin
            errors = errors + 1;
            $display("FAIL: grant without req: %b", grant);
        end

        // single requester always wins
        req = 4'b0100;
        #1;
        if (grant !== 4'b0100) begin
            errors = errors + 1;
            $display("FAIL: single requester not granted: %b", grant);
        end

        // all requesters: grant must be one-hot, subset of req, and rotate
        req = 4'b1111;
        g0 = 0; g1 = 0; g2 = 0; g3 = 0;
        for (i = 0; i < 16; i = i + 1) begin
            #1;
            if (!is_onehot_or_zero(grant)) begin
                errors = errors + 1;
                $display("FAIL: grant not one-hot: %b", grant);
            end
            if ((grant & req) !== grant) begin
                errors = errors + 1;
                $display("FAIL: grant not subset of req: %b", grant);
            end
            if (grant[0]) g0 = g0 + 1;
            if (grant[1]) g1 = g1 + 1;
            if (grant[2]) g2 = g2 + 1;
            if (grant[3]) g3 = g3 + 1;
            @(posedge clk);
        end
        // fairness over 16 cycles with all requesting: each gets ~4 grants
        if (g0 != 4 || g1 != 4 || g2 != 4 || g3 != 4) begin
            errors = errors + 1;
            $display("FAIL: unfair round-robin: %0d %0d %0d %0d", g0, g1, g2, g3);
        end

        if (errors == 0) begin
            $display("TEST PASSED");
        end else begin
            $display("TEST FAILED (%0d errors)", errors);
            $fatal(1);
        end
        $finish;
    end

    initial begin
        #100000;
        $display("TEST FAILED (timeout)");
        $fatal(1);
    end
endmodule
", "path": "/home/hshen/posttrain_v4flash/pipelines/rtl/seed_modules/tb/tb_round_robin_arbiter.v"}

{"content": "// Self-checking testbench for axis_skid_buffer: random valid/ready stalls,
// checks no beat is lost, duplicated, or reordered. Verilog-2001, iverilog-compatible.
`timescale 1ns/1ps
module tb_axis_skid_buffer;
    localparam WIDTH = 32;
    localparam N_BEATS = 200;

    reg                 clk = 1'b0;
    reg                 rst_n = 1'b0;
    reg  [WIDTH-1:0]    s_axis_tdata = {WIDTH{1'b0}};
    reg                 s_axis_tvalid = 1'b0;
    wire                s_axis_tready;
    wire [WIDTH-1:0]    m_axis_tdata;
    wire                m_axis_tvalid;
    reg                 m_axis_tready = 1'b0;

    integer sent = 0;
    integer received = 0;
    integer errors = 0;
    integer seed = 32'hdeadbeef;

    axis_skid_buffer #(.WIDTH(WIDTH)) dut (
        .clk(clk), .rst_n(rst_n),
        .s_axis_tdata(s_axis_tdata), .s_axis_tvalid(s_axis_tvalid),
        .s_axis_tready(s_axis_tready),
        .m_axis_tdata(m_axis_tdata), .m_axis_tvalid(m_axis_tvalid),
        .m_axis_tready(m_axis_tready)
    );

    always #5 clk = ~clk;

    // driver: randomized valid, data = beat index
    always @(posedge clk) begin
        if (!rst_n) begin
            s_axis_tvalid <= 1'b0;
            s_axis_tdata  <= {WIDTH{1'b0}};
        end else begin
            if (s_axis_tvalid && s_axis_tready) begin
                sent <= sent + 1;
                s_axis_tvalid <= ($random(seed) % 3 != 0);
                s_axis_tdata  <= sent + 1;
            end else if (!s_axis_tvalid) begin
                s_axis_tvalid <= ($random(seed) % 3 != 0) && (sent < N_BEATS);
                s_axis_tdata  <= sent;
            end
        end
    end

    // sink: randomized ready; check in-order delivery
    always @(posedge clk) begin
        if (!rst_n) begin
            m_axis_tready <= 1'b0;
        end else begin
            m_axis_tready <= ($random(seed) % 3 != 0);
            if (m_axis_tvalid && m_axis_tready) begin
                if (m_axis_tdata !== received) begin
                    errors = errors + 1;
                    $display("FAIL: expected beat %0d, got %0d at time %0t",
                             received, m_axis_tdata, $time);
                end
                received = received + 1;
            end
        end
    end

    initial begin
        repeat (4) @(posedge clk);
        rst_n = 1'b1;
        wait (received >= N_BEATS);
        repeat (2) @(posedge clk);
        if (errors == 0 && received == N_BEATS) begin
            $display("TEST PASSED");
        end else begin
            $display("TEST FAILED (%0d errors, received %0d/%0d)",
                     errors, received, N_BEATS);
            $fatal(1);
        end
        $finish;
    end

    initial begin
        #1000000;
        $display("TEST FAILED (timeout, received %0d/%0d)", received, N_BEATS);
        $fatal(1);
    end
endmodule
